import re
BANNED = ["לסיכום","ראשית","שנית","בנוסף לכך","יתרה מזאת","חשוב לציין","במסגרת","על מנת","כמו כן","יש לציין","לאחרונה"]
def wc(s): return len(s.split())
def check():
    problems = []
    src = json.load(open("/Users/s/niv-locksmith/agent_geo_input_5.json", encoding="utf-8"))
    names = [p["name"] for p in src]
    for n in names:
        if n not in data:
            problems.append(f"MISSING: {n}")
    for n, o in data.items():
        lw = wc(o["lead"])
        if not (40 <= lw <= 60):
            problems.append(f"[{n}] lead words={lw}")
        if len(o["sections"]) != 3:
            problems.append(f"[{n}] sections={len(o['sections'])}")
        for i, s in enumerate(o["sections"]):
            sw = wc(s["p"])
            if not (134 <= sw <= 167):
                problems.append(f"[{n}] section{i} words={sw}")
            if ":" in s["h"] or "—" in s["h"] or "–" in s["h"] or " - " in s["h"]:
                problems.append(f"[{n}] section{i} heading punctuation: {s['h']}")
        if not (4 <= len(o["specs"]) <= 6):
            problems.append(f"[{n}] specs={len(o['specs'])}")
        if len(o["faq"]) != 5:
            problems.append(f"[{n}] faq={len(o['faq'])}")
        blob = json.dumps(o, ensure_ascii=False)
        for b in BANNED:
            if b in blob:
                problems.append(f"[{n}] banned: {b}")
        if "—" in blob or "–" in blob:
            problems.append(f"[{n}] dash char present")
    return problems

if __name__ == "__main__":
    probs = check()
    if probs:
        print("PROBLEMS:", len(probs))
        for p in probs:
            print(" ", p)
    else:
        with open("/Users/s/niv-locksmith/agent_geo_out_5.json", "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        print("OK wrote", len(data))
